// --- Wave Curve Component ---
// Modified to S-Wave as per user's drawing, with double layer
const WaveCurve = ({ height = 80 }) => (
    <View style={{ width: '100%', height: height, marginTop: -1, zIndex: 0 }}>
        <Svg height={height} width={width} viewBox={`0 0 ${width} ${height}`} preserveAspectRatio="none">
            <Defs>
                <SvgGradient id="purpleGrad" x1="0%" y1="0%" x2="0%" y2="100%">
                    <Stop offset="0%" stopColor="#1e1259" stopOpacity="1" />
                    <Stop offset="100%" stopColor="#150d40" stopOpacity="0.8" />
                </SvgGradient>
            </Defs>

            {/* 
         Secondary "Light Pinkish" Wave (Layered Behind).
         Extends slightly lower (larger Y) to appear as a bottom rim/shadow.
      */}
            <Path
                d={`M0,${height * 0.7} 
            C${width * 0.35},${height * 0.1}, ${width * 0.65},${height}, ${width},${height * 0.7}
            L${width},0 L0,0 Z`}
                fill="#9B8BC4"
                fillOpacity="1"
            />

            {/* 
         Main Asymmetrical S-Wave (Foreground).
         Starts M 0, H*0.6
         Curves UP to Left Peak
         Curves DOWN to Right Trough
         Ends M W, H*0.6, using cubic bezier C.
      */}
            <Path
                d={`M0,${height * 0.6} 
            C${width * 0.35},${0}, ${width * 0.65},${height}, ${width},${height * 0.6}
            L${width},0 L0,0 Z`}
                fill="url(#purpleGrad)"
            />
        </Svg>
    </View>
);

const LoginScreen = ({ navigation }) => {
    const [loginType, setLoginType] = useState('mpin');
    const [mpin, setMpin] = useState(['', '', '', '', '', '']);
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [showPassword, setShowPassword] = useState(false);
    const [showHeader, setShowHeader] = useState(true);
    const mpinRefs = useRef([]);
    const insets = useSafeAreaInsets();

    const handleMpinChange = (value, index) => {
        if (/^\d*$/.test(value)) {
            const newMpin = [...mpin];
            if (value) {
                newMpin[index] = value;
                setMpin(newMpin);
                if (index < 5) {
                    mpinRefs.current[index + 1]?.focus();
                }
                if (newMpin.every(digit => digit !== '')) {
                    setTimeout(() => navigation.replace('Main'), 500);
                }
            } else {
                newMpin[index] = '';
                setMpin(newMpin);
            }
        }
    };

    const handleMpinKeyPress = (e, index) => {
        if (e.nativeEvent.key === 'Backspace' && !mpin[index] && index > 0) {
            mpinRefs.current[index - 1]?.focus();
        }
    };

    const handleLogin = () => {
        navigation.replace('Main');
    };

    return (
        <View style={styles.container}>
            <StatusBar barStyle="light-content" backgroundColor="#2b1874" />

            {/* Purple Background Container (Fixed Absolute) */}
            <View style={styles.purpleBgContainer}>
                <LinearGradient
                    colors={['#592d82', '#4a2470']}
                    style={styles.purpleBgMain}
                >
                    {/* Decorative Curved Lines on Purple Background - inward facing left */}
                    <Svg
                        width={width}
                        height={300}
                        style={{ position: 'absolute', top: -30, left: 0 }}
                    >
                        {/* Innermost curve (lightest - most visible) */}
                        <Path
                            d="M 100 -20 C 190 50, 210 150, 130 320"
                            stroke="rgba(255,255,255,0.12)"
                            strokeWidth={40}
                            fill="none"
                        />
                        {/* Middle curve */}
                        <Path
                            d="M 60 -20 C 170 60, 200 170, 100 340"
                            stroke="rgba(255,255,255,0.08)"
                            strokeWidth={50}
                            fill="none"
                        />
                        {/* Outermost curve (darker - subtle) */}
                        <Path
                            d="M 10 -20 C 140 70, 180 190, 60 360"
                            stroke="rgba(255,255,255,0.05)"
                            strokeWidth={60}
                            fill="none"
                        />
                    </Svg>

                    {/* Header Content */}
                    <View style={styles.headerContent}>
                        <View>
                            <Text style={styles.helloText}>Hello</Text>
                            <Text style={styles.userNameText}>Rahul</Text>
                        </View>
                        <View style={styles.headerRight}>
                            <Text style={styles.logoText}>
                                Yono<Text style={styles.logoDot}>●</Text>SBI
                            </Text>
                            <TouchableOpacity style={styles.locateUsBtn}>
                                <Ionicons name="location-outline" size={14} color="#fff" />
                                <Text style={styles.locateUsText}>Locate Us</Text>
                            </TouchableOpacity>
                        </View>
                    </View>
                </LinearGradient>
                {/* S-Wave Curve */}
                <WaveCurve height={90} />
            </View>

            {/* Main Content ScrollView */}
            <ScrollView
                style={styles.mainScrollView}
                contentContainerStyle={styles.scrollContent}
                showsVerticalScrollIndicator={false}
            >
                {/* Login Card floating on top */}
                <View style={styles.loginCard}>
                    {/* Card Header - conditionally rendered */}
                    {showHeader && (
                        <View style={styles.cardHeader}>
                            <Text style={styles.cardHeaderTitle}>View Balance</Text>
                            <TouchableOpacity style={styles.closeBtn} onPress={() => setShowHeader(false)}>
                                <Ionicons name="close" size={22} color="#666" />
                            </TouchableOpacity>
                        </View>
                    )}

                    {loginType === 'mpin' && (
                        <View style={styles.mpinSection}>
                            <Text style={styles.sectionTitle}>Login using MPIN</Text>
                            <View style={styles.mpinRow}>
                                {mpin.map((digit, index) => (
                                    <View key={index} style={styles.mpinInputWrapper}>
                                        <TextInput
                                            ref={(ref) => (mpinRefs.current[index] = ref)}
                                            style={styles.mpinInput}
                                            value={digit}
                                            onChangeText={(value) => handleMpinChange(value, index)}
                                            onKeyPress={(e) => handleMpinKeyPress(e, index)}
                                            keyboardType="numeric"
                                            maxLength={1}
                                            secureTextEntry
                                            textAlign="center"
                                        />
                                    </View>
                                ))}
                            </View>
                            <TouchableOpacity style={{ alignSelf: 'flex-end', marginTop: 10 }}>
                                <Text style={styles.forgotText}>Forgot MPIN?</Text>
                            </TouchableOpacity>
                        </View>
                    )}

                    <View style={styles.divider}>
                        <View style={styles.dividerLine} />
                        <Text style={styles.dividerText}>OR</Text>
                        <View style={styles.dividerLine} />
                    </View>

                    {loginType === 'mpin' && (
                        <View style={styles.loginWithUserContainer}>
                            <Text style={styles.loginWithUserText}>Login with <Text style={styles.loginWithUserLink}>Username</Text></Text>
                        </View>
                    )}

                    {loginType === 'username' && (
                        <View style={styles.usernameSection}>
                            <Text style={styles.sectionTitle}>Login using Username</Text>
                            <TextInput
                                style={styles.textInput}
                                placeholder="Username"
                                value={username}
                                onChangeText={setUsername}
                                placeholderTextColor="#999"
                            />
                            <View style={styles.passwordContainer}>
                                <TextInput
                                    style={[styles.textInput, { paddingRight: 44 }]}
                                    placeholder="Password"
                                    value={password}
                                    onChangeText={setPassword}
                                    secureTextEntry={!showPassword}
                                    placeholderTextColor="#999"
                                />
                                <TouchableOpacity style={styles.eyeIcon} onPress={() => setShowPassword(!showPassword)}>
                                    <Feather name={showPassword ? 'eye-off' : 'eye'} size={20} color="#888" />
                                </TouchableOpacity>
                            </View>
                            <TouchableOpacity>
                                <Text style={styles.forgotText}>Forgot Username or Password?</Text>
                            </TouchableOpacity>
                            <TouchableOpacity
                                style={[styles.loginBtn, (username && password) && styles.loginBtnActive]}
                                onPress={handleLogin}
                                disabled={!username || !password}
                            >
                                <Text style={[styles.loginBtnText, (username && password) && styles.loginBtnTextActive]}>
                                    Login
                                </Text>
                            </TouchableOpacity>
                            <TouchableOpacity onPress={() => setLoginType('mpin')} style={{ marginTop: 15, alignItems: 'center' }}>
                                <Text style={styles.optionText}>Login with <Text style={styles.optionBold}>MPIN</Text></Text>
                            </TouchableOpacity>
                        </View>
                    )}
                </View>

                {/* View Balance Button */}
                <TouchableOpacity style={styles.viewBalanceBtn} onPress={() => setShowHeader(true)}>
                    <Text style={styles.viewBalanceText}>View Balance</Text>
                </TouchableOpacity>

                {/* Tabs Row - Outside the card */}
                <View style={styles.tabsRow}>
                    <TouchableOpacity style={[styles.tab, styles.tabActive]}>
                        {/* Left curve notch */}
                        <View style={styles.tabNotchLeft}>
                            <Svg width="12" height="12" viewBox="0 0 12 12">
                                <Path d="M12,12 L12,0 C12,6.627 6.627,12 0,12 L12,12 Z" fill="#fff" />
                            </Svg>
                        </View>
                        {/* Right curve notch */}
                        <View style={styles.tabNotchRight}>
                            <Svg width="12" height="12" viewBox="0 0 12 12">
                                <Path d="M0,12 L0,0 C0,6.627 5.373,12 12,12 L0,12 Z" fill="#fff" />
                            </Svg>
                        </View>
                        <Text style={[styles.tabText, styles.tabTextActive]}>Transact</Text>
                        <View style={styles.tabUnderline} />
                    </TouchableOpacity>
                    <TouchableOpacity style={styles.tab}>
                        <Text style={styles.tabText}>Calculators</Text>
                    </TouchableOpacity>
                    <TouchableOpacity style={styles.tab}>
                        <Text style={styles.tabText}>Offers</Text>
                    </TouchableOpacity>
                </View>

                {/* White Card - Icons Section */}
                <View style={styles.transactCard}>
                    <View style={styles.iconsSection}>
                        <TouchableOpacity style={styles.quickAction}>
                            <View style={styles.quickIcon}>
                                <PayToMobileIcon size={40} color="#592d82" />
                            </View>
                            <Text style={styles.quickActionText}>Pay to{'\n'}Mobile or{'\n'}Contact</Text>
                        </TouchableOpacity>

                        <TouchableOpacity style={styles.quickAction}>
                            <View style={styles.quickIcon}>
                                <QuickTransferIcon size={40} color="#592d82" />
                            </View>
                            <Text style={styles.quickActionText}>Quick{'\n'}Transfer</Text>
                        </TouchableOpacity>

                        <TouchableOpacity style={styles.quickAction}>
                            <View style={styles.quickIcon}>
                                <SendMoneyIcon size={40} color="#592d82" />
                            </View>
                            <Text style={styles.quickActionText}>Send{'\n'}Money</Text>
                        </TouchableOpacity>

                        <TouchableOpacity style={styles.quickAction}>
                            <View style={styles.quickIcon}>
                                <BillPaymentsIcon size={40} />
                            </View>
                            <Text style={styles.quickActionText}>Bill{'\n'}Payments</Text>
                        </TouchableOpacity>
                    </View>
                </View>

                {/* Banner (Should be visible now) */}
                <View style={styles.npsBannerContainer}>
                    <Image
                        source={require('../../assets/images/nps_banner.png')}
                        style={styles.npsBannerImage}
                        resizeMode="cover"
                    />
                </View>
            </ScrollView>

            {/* Bottom Navigation with Curved Notch */}
            <View style={styles.bottomNavContainer}>
                {/* SVG Background with smooth curved hump in center */}
                <Svg
                    width={width}
                    height={150}
                    style={styles.bottomNavSvg}
                >
                    <Path
                        d={`M0,65 
                           L${width * 0.5 - 80},65 
                           C${width * 0.5 - 50},65 ${width * 0.5 - 45},20 ${width * 0.5},20
                           C${width * 0.5 + 45},20 ${width * 0.5 + 50},65 ${width * 0.5 + 80},65
                           L${width},65 
                           L${width},150 
                           L0,150 
                           Z`}
                        fill="#fff"
                    />
                </Svg>

                {/* Navigation Items */}
                <View style={styles.bottomNavItems}>
                    <TouchableOpacity style={styles.navItem}>
                        <YonoCashIcon size={22} color="#666" />
                        <Text style={styles.navText}>Yono Cash</Text>
                    </TouchableOpacity>

                    <TouchableOpacity style={styles.navItem}>
                        <ContactUsIcon size={22} color="#666" />
                        <Text style={styles.navText}>Contact Us</Text>
                    </TouchableOpacity>

                    {/* Center QR Button - positioned in the notch */}
                    <TouchableOpacity style={styles.navItemCenter}>
                        <View style={styles.scanQrBtn}>
                            <AnimatedQrIcon size={120} />
                        </View>
                        <Text style={styles.navTextCenter}>Scan QR</Text>
                    </TouchableOpacity>

                    <TouchableOpacity style={styles.navItem}>
                        <ProductsIcon size={22} color="#666" />
                        <Text style={styles.navText}>Products</Text>
                    </TouchableOpacity>

                    <TouchableOpacity style={styles.navItem}>
                        <Ionicons name="ellipsis-horizontal" size={22} color="#666" />
                        <Text style={styles.navText}>More</Text>
                    </TouchableOpacity>
                </View>
            </View>
        </View>
    );
};

